SET search_path TO lms, extensions;

CREATE TABLE events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  module_id UUID NOT NULL REFERENCES modules(id) ON DELETE CASCADE,
  created_by UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  deleted_at TIMESTAMPTZ
);

ALTER TABLE events ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Admins can manage events" ON events
  FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM users WHERE id = auth.uid() AND role = 'admin'));

CREATE POLICY "Teachers can manage their own events" ON events
  FOR ALL TO authenticated
  USING (created_by = auth.uid() AND EXISTS (SELECT 1 FROM users WHERE id = auth.uid() AND role = 'teacher'));

CREATE POLICY "Learners can view events" ON events
  FOR SELECT TO authenticated
  USING (deleted_at IS NULL);


CREATE TABLE event_attendances (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id UUID NOT NULL REFERENCES events(id) ON DELETE CASCADE,
  learner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE(event_id, learner_id)
);

ALTER TABLE event_attendances ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Admins can manage event_attendances" ON event_attendances
  FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM users WHERE id = auth.uid() AND role = 'admin'));

CREATE POLICY "Teachers can view attendances for their events" ON event_attendances
  FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM events WHERE events.id = event_id AND events.created_by = auth.uid()));

CREATE POLICY "Learners can view their own attendances" ON event_attendances
  FOR SELECT TO authenticated
  USING (learner_id = auth.uid());

CREATE POLICY "Learners can insert their own attendances" ON event_attendances
  FOR INSERT TO authenticated
  WITH CHECK (learner_id = auth.uid());
